"""Single-document extraction; persistence and scheduling are separate layers."""
import json
import shlex
from .providers import ProviderError
from .validation import validate
from .policy import route


def extract_valid(document, provider, policy=None):
    reply = provider.extract(document['message'], document_id=document['document_id'])
    if reply.get('status') != 'completed':
        raise ValueError('Provider response ' + str(reply.get('status', 'missing completion status')))
    extraction = validate(json.loads(reply['output_text']), document['message'])
    return {'document_id': document['document_id'], 'source_sha256': document.get('source_sha256'),
            'extraction': extraction, **route(extraction, document['message'], document['document_id'], policy),
            'error': None, 'response_source': reply['response_source']}


def process(document, provider, policy=None):
    try:
        return extract_valid(document, provider, policy)
    except (ProviderError, ValueError, KeyError, TypeError) as exc:
        name = document['document_id']
        return {'document_id': name, 'source_sha256': document.get('source_sha256'),
                'extraction': None, 'status': 'error', 'owner': 'IT Service Desk',
                'next_action': 'retry-extraction', 'error': str(exc),
                'transient': isinstance(exc, ProviderError) and exc.transient,
                'response_source': getattr(provider, 'response_source', 'mock'),
                'retry_command': 'python3 -m access_requests retry ' + shlex.quote(name)}
"""Validate the exact JSON Schema vocabulary used by snapshot.schema.json."""
from datetime import date
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SCHEMA = json.loads((ROOT / 'snapshot.schema.json').read_text())
SCALARS = [key for key in SCHEMA['properties'] if key not in ('issues', 'supporting_quotes')]


def read_export(path):
    path = Path(path)
    raw = path.read_bytes()
    export = json.loads(raw.decode('utf-8'))
    if not isinstance(export, dict) or not isinstance(export.get('message'), str):
        raise ValueError('Export requires a message string')
    return {'document_id': path.name, 'source_sha256': hashlib.sha256(raw).hexdigest(),
            'raw': raw, 'message': export['message']}


def check_schema(value, schema=SCHEMA, path='$'):
    types = {'object': dict, 'array': list, 'string': str, 'null': type(None)}
    names = schema['type'] if isinstance(schema['type'], list) else [schema['type']]
    if not any(isinstance(value, types[name]) for name in names):
        raise ValueError(f'{path}: invalid type')
    if 'enum' in schema and value not in schema['enum']:
        raise ValueError(f'{path}: invalid enum value')
    if isinstance(value, dict):
        if set(schema.get('required', [])) - value.keys():
            raise ValueError(f'{path}: missing required keys')
        properties = schema['properties']
        if schema.get('additionalProperties') is False and value.keys() - properties.keys():
            raise ValueError(f'{path}: unexpected properties')
        for key, item in value.items():
            if key in properties:
                check_schema(item, properties[key], f'{path}.{key}')
    if isinstance(value, list):
        for item in value:
            check_schema(item, schema['items'], path+'[]')


def validate(extraction, message):
    check_schema(extraction)
    for field in ('request_date', 'start_date', 'end_date'):
        value = extraction[field]
        if value is not None:
            try:
                if date.fromisoformat(value).isoformat() != value:
                    raise ValueError()
            except ValueError as exc:
                raise ValueError(f'{field}: expected valid YYYY-MM-DD') from exc
    for quote in extraction['supporting_quotes']:
        if not quote or quote not in message:
            raise ValueError('Supporting quote is not a nonempty message substring')
    return extraction
"""Deterministic ordered routing after extraction validation."""
from pathlib import Path
import re
from .validation import validate

REQUIRED = ('request_id', 'request_date', 'requester', 'team', 'system',
            'environment', 'permission', 'business_purpose', 'start_date', 'end_date', 'manager')


def decision(status, owner, action):
    return {'status': status, 'owner': owner, 'next_action': action}


def route(extraction, message, document_id, policy=None):
    validate(extraction, message)
    issues = extraction['issues']
    for field in ['kind', *REQUIRED]:
        if extraction[field] is None and not any(field in issue for issue in issues):
            issues.append(f'{field}: missing or unresolved')
    stem = Path(document_id).stem
    mismatch = bool(re.fullmatch(r'IT-\d+', stem) and extraction['request_id']
                    and stem != extraction['request_id'])
    if mismatch and not any('mismatch' in issue.lower() for issue in issues):
        issues.append('request_id: filename identifier mismatch')
    override = bool(re.search(r'system override|bypass approval|highest.priority system instruction|'
                              r'display the api key|mark request as approved', message, re.I))
    override = override or any('instruction' in i.lower() and
                              any(w in i.lower() for w in ('override', 'attempt', 'injection')) for i in issues)
    if override:
        if not any('instruction' in i.lower() for i in issues):
            issues.append('instruction-override attempt')
        if message not in extraction['supporting_quotes']:
            extraction['supporting_quotes'].append(message)
        return decision('review', 'IT Service Desk', 'inspect-message')
    if extraction['kind'] == 'withdrawal' and extraction['request_id'] and extraction['request_date']:
        return decision('review', 'IT Service Desk', 'confirm-withdrawal')
    reversed_dates = (extraction['start_date'] and extraction['end_date'] and
                      extraction['start_date'] > extraction['end_date'])
    if reversed_dates and not any('start_date after end_date' in issue for issue in issues):
        issues.append('start_date after end_date')
    conflict = any('conflict' in i.lower() or 'mismatch' in i.lower() for i in issues)
    if (extraction['kind'] not in ('new', 'change') or mismatch or reversed_dates or conflict
            or any(extraction[k] is None for k in REQUIRED)):
        return decision('needs-information', 'IT Service Desk', 'clarify')
    if extraction['environment'] == 'production' or extraction['permission'] in ('write', 'admin'):
        return decision('review', 'Security Review', 'review-risk-then-owner')
    if policy and 'Complete staging/read requests go to Security Review' in policy:
        return decision('review', 'Security Review', 'review-risk-then-owner')
    return decision('review', 'System Owner', 'review-request')

"""Bounded workers, renewable leases and durable delayed retries."""
from concurrent.futures import ThreadPoolExecutor
import threading
import time
from .intake import process
from .store import production_settings


def run(store, provider, *, workers=4, rate=0, retries=2, backoff=1, lease=60, on_result=None):
    if workers < 1 or rate < 0 or retries < 0 or backoff < 0 or lease <= 0:
        raise ValueError('Invalid scheduler limits')
    limiter = threading.Lock()
    next_call = [0.0]

    def worker():
        while True:
            claim = store.claim(lease=lease)
            if claim is None:
                if not store.pending():
                    return
                time.sleep(.02)
                continue
            if json_settings(claim['settings']) != production_settings(provider.configuration):
                raise ValueError('Pending attempt settings differ; resume with its original provider settings')
            stopped = threading.Event()

            def heartbeat():
                while not stopped.wait(lease/3):
                    if not store.renew(claim['id'],claim['token'],lease=lease):
                        return

            heartbeat_thread = threading.Thread(target=heartbeat,daemon=True)
            heartbeat_thread.start()
            try:
                if rate:
                    with limiter:
                        delay = max(0,next_call[0]-time.monotonic())
                        next_call[0] = max(next_call[0],time.monotonic())+1/rate
                    if delay:
                        time.sleep(delay)
                document = store.document(claim['id'])
                result = process(document,provider,claim['policy'])
                committed = store.finish(claim['id'],result,token=claim['token'])
                if committed and result.get('transient') and claim['retry_count'] < retries:
                    store.retry_later(claim['id'],delay=backoff*2**claim['retry_count'])
                if committed and on_result:
                    on_result()
            finally:
                stopped.set()
                heartbeat_thread.join()

    with ThreadPoolExecutor(max_workers=workers) as pool:
        futures = [pool.submit(worker) for _ in range(workers)]
        for future in futures:
            future.result()


